import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Comanda } from '../../comandas/entities/comanda.entity';
import { Cocinero } from '../../cocineros/entities/cocinero.entity';

@Injectable()
export class AsignarCocineroRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Comanda) private readonly comandas: Repository<Comanda>,
    @InjectRepository(Cocinero) private readonly cocineros: Repository<Cocinero>
  ) {}

  buscarComandaRepository(comandaId: number) {
    return this.comandas.findOneBy({ id: comandaId });
  }

  buscarCocineroRepository(cocineroId: number) {
    return this.cocineros.findOneBy({ id: cocineroId });
  }

  async asignarCocineroRepository(comandaId: number, cocineroId: number, rol: string) {
    const asignacion = { comandaId, cocineroId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarCocineroRepository } from './repository';

@Injectable()
export class AsignarCocineroService {
  constructor(private readonly repository: AsignarCocineroRepository) {}

  async asignarCocineroService(comandaId: number, cocineroId: number, rol: string) {
    const comanda = await this.repository.buscarComandaRepository(comandaId);
    const cocinero = await this.repository.buscarCocineroRepository(cocineroId);
    if (!comanda || !cocinero) {
      throw new NotFoundException('No existe la comanda o el cocinero');
    }

    try {
      return await this.repository.asignarCocineroRepository(comandaId, cocineroId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El cocinero ya está asignado a esa comanda');
      }
      throw error;
    }
  }
}

